CREATE TABLE help_posts (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES profiles(id),community_id UUID REFERENCES communities(id),type VARCHAR(20) NOT NULL,title VARCHAR(160) NOT NULL,description VARCHAR(2000) NOT NULL,status VARCHAR(20) NOT NULL,is_emergency BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT chk_help_type CHECK(type IN ('NEED','OFFER','EXCHANGE')),CONSTRAINT chk_help_status CHECK(status IN ('OPEN','IN_PROGRESS','RESOLVED','CANCELLED')));
CREATE TABLE help_responses (id UUID PRIMARY KEY,help_post_id UUID NOT NULL REFERENCES help_posts(id) ON DELETE CASCADE,responder_id UUID NOT NULL REFERENCES profiles(id),message VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE emergency_alerts (id UUID PRIMARY KEY,type VARCHAR(50) NOT NULL,source VARCHAR(120) NOT NULL,title VARCHAR(160) NOT NULL,description VARCHAR(2000),zone VARCHAR(255),issued_at TIMESTAMP WITH TIME ZONE NOT NULL,expires_at TIMESTAMP WITH TIME ZONE,status VARCHAR(20) NOT NULL);
CREATE TABLE emergency_points (id UUID PRIMARY KEY,name VARCHAR(160) NOT NULL,description VARCHAR(1000),latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,address VARCHAR(255),source VARCHAR(120),verified_at TIMESTAMP WITH TIME ZONE,status VARCHAR(20) NOT NULL);
CREATE TABLE user_locations (user_id UUID PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,sharing_enabled BOOLEAN NOT NULL DEFAULT FALSE);
